input.sparql:
SELECT ?zone ?tempSeries ?heatSetpointSeries ?coolSetpointSeries WHERE {
  ?zone a brick:Zone ;
    bf:hasPoint/brick:hasTimeseries ?tempSeries ;
    bf:hasPoint/brick:hasTimeseries ?heatSetpointSeries , ?coolSetpointSeries ;
    brick:hasName "Core_mid".
  ?tempSeries ref:hasTimeseriesId ?tempId.
  ?heatSetpointSeries ref:hasTimeseriesId ?heatSetpointId.
  ?coolSetpointSeries ref:hasTimeseriesId ?coolSetpointId.
}
